RAW=sql("WITH scoped_items AS (\n SELECT s.id,s.novel_id FROM novel_source_item s JOIN channel_app ca ON ca.id=s.channel_app_id JOIN source_app sa ON sa.id=ca.source_app_id WHERE sa.code='moboreader' AND s.external_agency_id='1351'\n), scoped_promos AS (SELECT p.id FROM promo_link p JOIN scoped_items s ON s.id=p.novel_source_item_id), targets AS (\n SELECT id::text AS id FROM scoped_items UNION SELECT novel_id::text FROM scoped_items WHERE novel_id IS NOT NULL UNION SELECT a.id::text FROM article a JOIN scoped_promos p ON p.id=a.promo_link_id\n), bg AS (\n SELECT t.id AS task_id,t.task_type,t.status AS task_status,t.parent_task_id,p.task_type AS parent_type,p.status AS parent_status,i.status AS item_status,count(*) AS items FROM generic_task_item i JOIN generic_task t ON t.id=i.task_id LEFT JOIN generic_task p ON p.id=t.parent_task_id WHERE i.status IN ('pending','processing') AND i.target_id IN (SELECT id FROM targets) GROUP BY t.id,t.task_type,t.status,t.parent_task_id,p.task_type,p.status,i.status\n), bs AS (\n SELECT t.id AS task_id,t.task_type,t.status AS task_status,i.status AS item_status,count(*) AS items FROM channel_sync_task_item i JOIN channel_sync_task t ON t.id=i.task_id WHERE i.status IN ('pending','processing') AND i.novel_source_item_id IN (SELECT id FROM scoped_items) GROUP BY t.id,t.task_type,t.status,i.status\n), scans AS (\n SELECT id AS task_id,task_type,status AS task_status,channel_app_id FROM generic_task WHERE task_type='catalog_scan' AND status IN ('pending','processing')\n), claims AS (\n SELECT t.id AS task_id,t.status AS task_status,t.parent_task_id,p.status AS parent_status,\n count(i.id) FILTER(WHERE i.status IN ('pending','processing')) AS unfinished_items,\n count(i.id) FILTER(WHERE i.status IN ('pending','processing') AND s.external_agency_id='1351') AS unfinished_1351,\n count(i.id) FILTER(WHERE i.status IN ('pending','processing') AND s.external_agency_id='3366') AS unfinished_3366,\n count(i.id) FILTER(WHERE i.status IN ('pending','processing') AND s.id IS NULL) AS unresolved_unfinished_targets\n FROM generic_task t LEFT JOIN generic_task p ON p.id=t.parent_task_id LEFT JOIN generic_task_item i ON i.task_id=t.id LEFT JOIN novel_source_item s ON s.id::text=i.target_id\n WHERE t.task_type='promo_link.claim.v1' AND (t.status IN ('pending','processing','paused','disabled') OR EXISTS(SELECT 1 FROM generic_task_item u WHERE u.task_id=t.id AND u.status IN ('pending','processing')))\n GROUP BY t.id,t.status,t.parent_task_id,p.status\n), parents AS (\n SELECT t.id AS task_id,t.status AS task_status,t.params->>'operation' AS operation,t.params->'selection'->>'scope' AS selection_scope,\n (SELECT count(*) FROM generic_task c WHERE c.parent_task_id=t.id AND c.status IN ('pending','processing','paused','disabled')) AS unfinished_children,\n (SELECT count(*) FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(t.params->'selection'->'ids')='array' THEN t.params->'selection'->'ids' ELSE '[]'::jsonb END) v(id) JOIN scoped_items s ON s.id::text=v.id) AS explicitly_selected_1351\n FROM generic_task t WHERE t.task_type='batch.materialize.v1' AND t.params->>'operation'='promo_claim' AND t.status IN ('pending','processing','paused','disabled')\n)\nSELECT json_build_object('readAt',clock_timestamp(),'candidateSourceItems',(SELECT count(*) FROM scoped_items),'pendingGenericTaskItems',(SELECT coalesce(sum(items),0) FROM bg),'pendingSyncTaskItems',(SELECT coalesce(sum(items),0) FROM bs),'activeCatalogScans',(SELECT count(*) FROM scans),'genericBlockingTasks',coalesce((SELECT json_agg(bg ORDER BY task_id,item_status) FROM bg),'[]'::json),'syncBlockingTasks',coalesce((SELECT json_agg(bs ORDER BY task_id,item_status) FROM bs),'[]'::json),'catalogScans',coalesce((SELECT json_agg(scans ORDER BY task_id) FROM scans),'[]'::json),'claimShards',coalesce((SELECT json_agg(claims ORDER BY task_id) FROM claims),'[]'::json),'claimParents',coalesce((SELECT json_agg(parents ORDER BY task_id) FROM parents),'[]'::json));\n")
x=next(json.loads(l) for l in RAW.splitlines() if l.startswith('{'));print('COMPLETE_TASK_INVENTORY='+json.dumps(x,ensure_ascii=False));print('TASK_INVENTORY=COMPLETE no_sample_limit=true')
